import sys
sys.path.insert(0, r'token-master-plugin\skills\token-master')
from brainspace.jev import is_high_confidence, ValidationError
for kind, key in [('choice', 'confidence'), ('score', 'confidence'), ('noul', 'noul')]:
    for value in (0, 0.1, 0.5, 0.79, 0.8, 1):
        answer = {'type': kind, key: value}
        original = answer.copy()
        for threshold in (0, 0.8, 1):
            confidence = max(value, 1-value) if kind == 'noul' else value
            assert is_high_confidence(answer, threshold) == (confidence >= threshold)
        assert answer == original
for threshold in (True, False, None, '0.8', float('nan'), float('inf'), -0.1, 1.1, 10**400):
    try:
        is_high_confidence({'type': 'noul', 'noul': 1}, threshold)
    except ValidationError as exc:
        assert str(exc) == 'invalid_threshold'
    else:
        raise AssertionError(threshold)
for answer in (None, [], {}, {'type': 'other'}, {'type': []}, {'type': 'choice'}, {'type': 'score', 'confidence': True}, {'type': 'noul', 'noul': float('nan')}, {'type': 'noul', 'noul': 2}):
    try:
        is_high_confidence(answer)
    except ValidationError as exc:
        assert str(exc) == 'invalid_response'
    else:
        raise AssertionError(answer)
